using Idb.Libraries.Abstractions.Services;

namespace Idb.Libraries.Implementation.Factories;

/// <summary>
/// Default implementation that echoes the normalized identifier generated by the writer.
/// </summary>
public sealed class DefaultFileNameFactory : IFileNameFactory
{
    public string Create(object value, string normalizedId, Type contractType)
    {
        if (string.IsNullOrWhiteSpace(normalizedId))
        {
            throw new ArgumentException("Normalized id cannot be null or whitespace.", nameof(normalizedId));
        }

        return normalizedId;
    }
}
